42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	};
51	
52	const FIRST_INSURANCE_PERCENT = 10;
53	
54	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
55	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
56	// is 110.00000000000001 in binary floating point. Since the final amount feeds
57	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
58	const addPercent = (amount: number, percent: number): number =>
59	  amount + (amount * percent) / 100;
60	
61	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
62	
63	const quotePremium = (step: QuoteStep): number => {
64	  const policyBasePremium = step.items.reduce(
65	    (sum, item) => sum + basePremiumOf(item),
66	    0,
67	  );
68	  return Math.ceil(
69	    addPercent(policyBasePremium, FIRST_INSURANCE_PERCENT) + PROCESSING_FEE,
70	  );
71	};
72	
73	const runStep = (step: Step): StepResult => {
74	  if (step.op === "quote") return { premium: quotePremium(step) };
75	  throw new Error(`Unsupported step: ${step.op}`);
76	};
77	
78	export const runScenario = (scenario: Scenario): ScenarioResult => ({
79	  results: scenario.steps.map(runStep),
80	});
